package com.htttdn.crm.dto.admin;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public final class AdminDtos { private AdminDtos(){} public record UserRequest(@NotBlank String fullName,String phone,String preferences){} public record LockRequest(boolean locked){} public record FeedbackRequest(String status,String adminResponse){} public record StatusRequest(@NotBlank String status){} public record StockRequest(@Min(0) int quantity){} public record ProductRequest(@NotBlank String name,String category,String description,@NotNull @DecimalMin("0.0") BigDecimal price,@Min(0) int stock,String imageUrl){} public record QuestionRequest(@NotBlank String text,@NotBlank String type,String optionsJson){} public record SurveyRequest(@NotBlank String title,String description,Instant startsAt,Instant endsAt,List<QuestionRequest> questions){public SurveyRequest{if(questions==null)questions=List.of();}} }
